CREATE TABLE "JobBoardPosting" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "vacancyId" TEXT NOT NULL, "provider" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "externalPostingId" TEXT, "externalUrl" TEXT, "trackingCode" TEXT NOT NULL, "publishedAt" TIMESTAMP(3), "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "JobBoardPosting_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmployeeReferral" ("id" TEXT NOT NULL, "tenantId" TEXT NOT NULL, "vacancyId" TEXT NOT NULL, "referrerUserId" TEXT NOT NULL, "referralCode" TEXT NOT NULL, "candidateEmail" TEXT, "candidateName" TEXT, "applicationId" TEXT, "acceptedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmployeeReferral_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "JobBoardPosting_trackingCode_key" ON "JobBoardPosting"("trackingCode"); CREATE UNIQUE INDEX "JobBoardPosting_vacancyId_provider_key" ON "JobBoardPosting"("vacancyId", "provider"); CREATE UNIQUE INDEX "EmployeeReferral_referralCode_key" ON "EmployeeReferral"("referralCode"); CREATE UNIQUE INDEX "EmployeeReferral_applicationId_key" ON "EmployeeReferral"("applicationId");
ALTER TABLE "JobBoardPosting" ADD CONSTRAINT "JobBoardPosting_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE; ALTER TABLE "JobBoardPosting" ADD CONSTRAINT "JobBoardPosting_vacancyId_fkey" FOREIGN KEY ("vacancyId") REFERENCES "Vacancy"("id") ON DELETE CASCADE; ALTER TABLE "EmployeeReferral" ADD CONSTRAINT "EmployeeReferral_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE; ALTER TABLE "EmployeeReferral" ADD CONSTRAINT "EmployeeReferral_vacancyId_fkey" FOREIGN KEY ("vacancyId") REFERENCES "Vacancy"("id") ON DELETE CASCADE;
